/** Phase 0 API: builds the default theme from the token source in `cwd` and writes every output. */
export async function compile({
  cwd,
  outDir = join(cwd, "dist"),
}: {
  cwd: string;
  /** Where the outputs are written; defaults to `<cwd>/dist`. */
  outDir?: string;
}): Promise<string[]> {
  const result = build(DEFAULT_CONFIG, { sourceDir: cwd });
  for (const warning of result.warnings) console.warn(`warning: ${warning}`);
  return writeOutputs(result, outDir);
}
